'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={view:'setup',step:0,domain:0,focus:'LLVM / Clang',custom:'',progress:0,paused:false,generating:false,profiles:[],selected:0,settingsTab:0,theme:'dark',size:23,bilingual:true,originalFirst:false,dock:true,opacity:96,autoSave:true,connected:true,running:false,started:false,tick:0,search:''};
let generationTimer,playTimer,toastTimer,editId,lastFrame=0,lastPaint=0;
const sentences=[['今天，我们来看看 Clang 如何理解一段 C++ 代码。','Today, let’s look at how Clang understands a piece of C++ code.'],['解析器构建 AST，Sema 随后检查表达式的语义。','The parser builds the AST. Sema then checks the semantics of expressions.'],['如果类型不匹配，Clang 会在这个阶段给出诊断信息。','If the types do not match, Clang produces a diagnostic at this stage.'],['这些信息最终会被转换为 LLVM IR，交给后续的优化流程。','This information is eventually lowered to LLVM IR for subsequent optimization.']];
const symbols=['⌘','◇','↗','⌬','☷','＋'];
const brand=()=>`<span class="brand"><span class="brand-symbol"><i></i><i></i><i></i><i></i></span>Livecap</span>`;
const wave=()=>`<span class="wave ${S.running||S.generating&&!S.paused?'live-wave':''}" aria-hidden="true">${'<i></i>'.repeat(7)}</span>`;
function notify(t){$('#notice').textContent=t;$('#notice').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#notice').hidden=true,2500)}
function current(){return S.profiles[S.selected]}
function go(view){S.view=view;location.hash=view;render()}
function render(){if(S.view==='setup')$('#root').innerHTML=onboarding();else $('#root').innerHTML=`${header()}<main class="screen">${S.view==='library'?library():workspace()}</main>`;updateProgress();paintCaptions()}
function header(){return `<header class="app-header">${brand()}<nav aria-label="主导航"><button data-go="workspace" class="${S.view==='workspace'?'active':''}">字幕</button><button data-go="library" class="${S.view==='library'?'active':''}">知识库</button></nav><div class="header-end"><span class="product-tag">设计预览</span><button data-action="settings" aria-label="打开设置">⚙</button><span class="avatar">L</span></div></header>`}
function onboarding(){return `<main class="onboarding"><aside class="onboard-story">${brand()}<div class="story-body"><div class="story-number">YOUR WORDS. UNDERSTOOD.</div><h2>听见每一句。<br><span>听懂每一层意思。</span></h2><p>为你熟悉的领域准备专业词汇，<br>让字幕跟上讨论的深度。</p><div class="story-preview"><div class="caption-top"><span>说话人 1</span><span>EN → 中文</span></div><p>在 <mark>Clang</mark> 中，<mark>Sema</mark> 负责语义分析。</p><small>In Clang, Sema is responsible for semantic analysis.</small></div></div><div class="story-footer"><span>实时转录</span><span>双语字幕</span><span>专业语境</span></div></aside><section class="onboard-main"><div class="onboard-top"><span class="product-tag">设计预览</span><button class="text-btn small" data-action="skip">${S.profiles.length?'返回工作区':'稍后设置'} ↗</button></div><div class="wizard fade">${S.step===0?chooseDomain():S.step===1?generation():ready()}</div></section></main>`}
function chooseDomain(){return `<div class="step-label">第 1 步，共 3 步</div><h1>你经常听哪类内容？</h1><p class="subtitle">${S.profiles.length?'选择一个领域，添加到你的知识库。':'选择一个领域，建立你的第一份知识库。'}</p><div class="domain-grid" role="group" aria-label="选择领域">${domains.map((d,i)=>`<button class="domain-choice ${S.domain===i?'selected':''}" data-domain="${i}" aria-pressed="${S.domain===i}"><span class="choice-icon">${symbols[i]}</span><span><strong>${d.name}</strong><small>${d.desc}</small></span></button>`).join('')}</div><div class="focus-box"><label for="custom">${S.domain===5?'领域名称':'细分方向'}</label>${S.domain===5?`<input id="custom" placeholder="例如：半导体制造" value="${esc(S.custom)}" maxlength="80">`:`<div class="focus-chips">${domains[S.domain].focus.map(f=>`<button data-focus="${f}" class="${S.focus===f?'selected':''}" aria-pressed="${S.focus===f}">${f}</button>`).join('')}</div>`}</div><div class="wizard-actions"><small>之后可以添加更多领域</small><button class="primary" data-action="generate" ${S.domain===5&&!S.custom.trim()?'disabled':''}>生成知识库 <span style="margin-left:17px">→</span></button></div>${steps(0)}`}
function steps(n){return `<div class="wizard-footer" aria-label="步骤 ${n+1} / 3">${[0,1,2].map(i=>`<i class="${i<=n?'active':''}"></i>`).join('')}</div>`}
function generation(){return `<div class="generation-icon">${wave()}</div><div class="step-label">第 2 步，共 3 步</div><h1>正在准备你的知识库</h1><p class="subtitle">${esc(S.domain===5?S.custom:S.focus)}</p><div class="progress-line" role="progressbar" aria-label="生成进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${S.progress}"><span id="progress"></span></div><div class="generation-meta"><span id="progress-status">整理中</span><span id="percent">${S.progress}%</span></div>${[['查找参考资料','筛选与你的领域相关的公开文档'],['提炼词汇与表达','整理专有名词、缩写与常见译法'],['保存知识库','下次使用时自动加载']].map((x,i)=>`<div class="generation-row" data-stage="${i}"><span class="circle">${i+1}</span><div><h3>${x[0]}</h3><p>${x[1]}</p></div></div>`).join('')}<div class="wizard-actions"><button class="text-btn small" data-action="cancel">取消</button><button class="small" data-action="pause-generation">${S.paused?'继续':'暂停'}</button></div>${steps(1)}`}
function updateProgress(){if(!$('#progress'))return;$('#progress').style.width=S.progress+'%';$('#percent').textContent=S.progress+'%';$('.progress-line').setAttribute('aria-valuenow',S.progress);$('#progress-status').textContent=S.paused?'已暂停':'整理中';document.querySelectorAll('[data-stage]').forEach((el,i)=>{let n=Math.min(2,Math.floor(S.progress/34));el.classList.toggle('active',i===n);el.classList.toggle('complete',i<n);el.querySelector('.circle').textContent=i<n?'✓':i+1})}
function startGeneration(){S.step=1;S.progress=0;S.paused=false;S.generating=true;render();clearInterval(generationTimer);generationTimer=setInterval(()=>{if(S.paused)return;S.progress=Math.min(100,S.progress+2);updateProgress();if(S.progress===100){clearInterval(generationTimer);S.generating=false;const d=domains[S.domain],terms=S.domain===0&&programmingExamples[S.focus]||d.terms;const special=S.domain===0&&S.focus!=='LLVM / Clang';const name=S.domain===5?S.custom:S.focus;const profile={name,category:d.name,source:special?'技术术语':d.source,url:special?'':d.url,terms:terms.map((t,i)=>({id:i,term:t[0],translation:t[1],meaning:t[2]})),sample:true};const exists=S.profiles.findIndex(p=>p.name===name);if(exists>=0){S.profiles[exists]=profile;S.selected=exists}else{S.profiles.push(profile);S.selected=S.profiles.length-1}S.search='';S.step=2;if(S.view==='setup')render();else notify('知识库已就绪')}},160)}
function ready(){const p=current();return `<div class="complete-badge">✓</div><div class="step-label">第 3 步，共 3 步</div><h1>准备好了</h1><p class="subtitle">${esc(p.name)} 已添加到你的知识库。</p><div class="result-summary"><div class="result-head"><strong>${esc(p.name)}</strong><span>${p.terms.length} 个术语</span></div>${p.terms.slice(0,4).map(t=>`<div class="preview-term"><strong>${esc(t.term)}</strong><span>${esc(t.translation)}</span></div>`).join('')}</div><div class="saved-line">✓ ${S.autoSave?'自动保存到本地':'已添加到本次会话'}</div><div class="wizard-actions"><button class="text-btn small" data-go="library">查看全部术语</button><button class="primary" data-go="workspace">进入工作区 →</button></div>${steps(2)}`}
function segments(key,options){return `<div class="segments" role="group" aria-label="${key}">${options.map(([v,t])=>`<button data-setting="${key}" data-value="${v}" class="${String(S[key])===String(v)?'active':''}" aria-pressed="${String(S[key])===String(v)}">${t}</button>`).join('')}</div>`}
function caption(){return `<div class="caption ${S.theme==='light'?'light':''} ${S.originalFirst?'original-first':''} ${S.bilingual?'':'zh-only'}"><div class="caption-top"><span>说话人 1</span><span>EN → 中文</span></div><div class="caption-copy"><div class="caption-zh"></div><div class="caption-en"></div></div></div>`}
function workspace(){return `<div class="page-heading"><div><h1>${S.started?'当前会话':'开始一次新的聆听'}</h1><p class="subtitle">${S.started?'系统音频 · 英语 → 简体中文':'会议、视频或播客，打开字幕即可开始。'}</p></div><span class="status ${S.running?'live':''}"><i></i>${S.running?'正在聆听':S.started?'已暂停':'准备就绪'}</span></div><div class="workspace-grid ${S.started?'session-active':''}"><aside><div class="panel"><div class="control-content"><div class="field"><span class="field-label">声音来源</span><div class="source-display"><span class="source-glyph">▣</span><span>系统音频<small>当前播放的声音</small></span></div></div><div class="field"><span class="field-label">翻译方向</span><div class="language-pair"><span>英语</span><b>→</b><span>简体中文</span></div></div><div class="field"><span class="field-label">知识库</span><button class="context-button" data-go="library">${current()?esc(current().name):'通用'}<span>↗</span></button></div><button class="primary begin" data-action="play">${S.running?'Ⅱ 暂停字幕':S.started?'▷ 继续字幕':'▷ 开始字幕'}</button></div><div class="control-foot"><span>OpenAI · Luna</span><button class="text-btn small" data-action="connection" aria-label="连接设置">设置 ↗</button></div></div><div class="cost-card panel"><span>本次预计费用</span><strong>$0.00</strong></div></aside><section class="panel transcript"><div class="panel-title"><h3>会话记录</h3><small id="timer">${time()}</small></div><div class="transcript-content" id="transcript">${transcript()}</div></section></div><section class="session-strip"><div class="strip-toolbar"><span>字幕窗口</span><div style="display:flex;gap:10px;align-items:center">${segments('dock',[[true,'底部停靠'],[false,'悬浮']])}<button class="text-btn small" data-action="settings" aria-label="调整字幕外观">Aa</button></div></div><div class="overlay-holder ${S.dock?'docked':''}">${caption()}</div></section>`}
function time(){return String(Math.floor(S.tick/60)).padStart(2,'0')+':'+String(Math.floor(S.tick%60)).padStart(2,'0')}
function sentence(){return sentences[Math.floor(S.tick/7)%sentences.length]}
function partial(){const [zh,en]=sentence();if(!S.started)return [zh,en];const phase=S.tick%7,ratio=Math.min(1,(phase+.25)/5.6);const units=zh.match(/[A-Za-z][A-Za-z+\/-]*|./gu)||[];const words=en.split(' ');return [units.slice(0,Math.max(1,Math.floor(units.length*ratio))).join(''),words.slice(0,Math.max(1,Math.floor(words.length*ratio))).join(' ')]}
function turnMarkup(i,n){const [zh,en]=i===n?partial():sentences[i%sentences.length];return `<article class="turn ${i===n&&S.running?'current':''}" data-turn="${i}"><div class="turn-meta"><span class="speaker">1</span><span>说话人 1</span><span>${String(Math.floor(i*7/60)).padStart(2,'0')}:${String(i*7%60).padStart(2,'0')}</span></div><p class="turn-zh">${zh}</p><p class="turn-en">${en}</p></article>`}
function transcript(){if(!S.started)return `<div class="transcript-empty">${wave()}<div><strong>等待开始</strong><p>转写与译文将在这里同步显示</p></div></div>`;const n=Math.floor(S.tick/7);let html='';for(let i=Math.max(0,n-11);i<=n;i++)html+=turnMarkup(i,n);return html}
function textIfChanged(el,value){if(el&&el.textContent!==value)el.textContent=value}
function paintCaptions(){const [zh,en]=S.started?partial():['字幕会显示在这里','Your live captions will appear here.'];document.querySelectorAll('.caption').forEach(el=>{el.classList.toggle('light',S.theme==='light');el.classList.toggle('original-first',S.originalFirst);el.classList.toggle('zh-only',!S.bilingual);el.style.background=S.theme==='light'?`rgba(255,255,255,${S.opacity/100})`:`rgba(33,39,53,${S.opacity/100})`;el.querySelector('.caption-zh').style.fontSize=S.size+'px';textIfChanged(el.querySelector('.caption-zh'),zh);textIfChanged(el.querySelector('.caption-en'),en)});textIfChanged($('#timer'),time())}
function updateTranscript(){const list=$('#transcript');if(!list)return;const n=Math.floor(S.tick/7),follow=list.scrollHeight-list.clientHeight-list.scrollTop<48,oldHeight=list.scrollHeight;let active=list.querySelector(`[data-turn="${n}"]`);if(!active){list.querySelector('.transcript-empty')?.remove();list.querySelectorAll('.current').forEach(el=>{const i=Number(el.dataset.turn);el.classList.remove('current');const [zh,en]=sentences[i%sentences.length];textIfChanged(el.querySelector('.turn-zh'),zh);textIfChanged(el.querySelector('.turn-en'),en)});list.insertAdjacentHTML('beforeend',turnMarkup(n,n));active=list.querySelector(`[data-turn="${n}"]`);while(list.children.length>12)list.firstElementChild.remove()}const [zh,en]=partial();textIfChanged(active.querySelector('.turn-zh'),zh);textIfChanged(active.querySelector('.turn-en'),en);if(follow&&list.scrollHeight!==oldHeight)list.scrollTo({top:list.scrollHeight,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function tick(now){if(!S.running)return;const delta=lastFrame?Math.min(now-lastFrame,250):0;lastFrame=now;S.tick+=delta/1000;if(now-lastPaint>=90){lastPaint=now;updateTranscript();paintCaptions()}playTimer=requestAnimationFrame(tick)}
function togglePlayback(){S.running=!S.running;S.started=true;cancelAnimationFrame(playTimer);lastFrame=0;lastPaint=0;if(S.running)playTimer=requestAnimationFrame(tick);render();const list=$('#transcript');if(list)list.scrollTop=list.scrollHeight}
function library(){return `<div class="page-heading"><div><h1>知识库</h1><p class="subtitle">用于转录与翻译的专业词汇。</p></div><button class="primary small" data-action="new">＋ 新建知识库</button></div>${!S.profiles.length?`<div class="panel empty-library"><h2>添加你的第一个领域</h2><p>生成术语、缩写与常见译法。</p><button class="primary" data-action="new">选择领域 →</button></div>`:`<div class="library-grid"><aside class="library-list">${S.profiles.map((p,i)=>`<button class="profile-item ${S.selected===i?'active':''}" data-profile="${i}"><strong>${esc(p.name)}${S.selected===i?'<span class="active-dot">●</span>':''}</strong><small>${esc(p.category)} · ${p.terms.length} 个术语</small></button>`).join('')}</aside><section class="panel"><div class="table-toolbar"><input class="search" id="search" aria-label="搜索术语" placeholder="搜索术语或译法" value="${esc(S.search)}"><span>${current().terms.length} 个术语</span></div><table class="terms-table"><thead><tr><th>术语</th><th>译法</th><th style="width:45px"></th></tr></thead><tbody id="term-rows">${termRows()}</tbody></table><div class="table-bottom"><button class="text-btn small" data-action="export">↓ 导出 JSON</button><button class="primary small" data-go="workspace">使用此知识库 →</button></div></section></div>`}`}
function termRows(){const rows=current().terms.filter(t=>(t.term+t.translation).toLowerCase().includes(S.search.toLowerCase()));return rows.length?rows.map(t=>`<tr><td><button data-term="${t.id}">${esc(t.term)}</button><small>${esc(current().source)}</small></td><td>${esc(t.translation)}</td><td><button data-term="${t.id}" aria-label="编辑 ${esc(t.term)}">↗</button></td></tr>`).join(''):'<tr><td colspan="3">没有匹配的术语</td></tr>'}
function setting(label,control,desc=''){return `<div class="setting"><div>${label}${desc?`<small>${desc}</small>`:''}</div>${control}</div>`}
function settingsContent(){let body='';if(S.settingsTab===0)body=`<h3>字幕外观</h3>${setting('主题',segments('theme',[['dark','深色'],['light','浅色']]))}${setting('字号',`<div class="range"><input aria-label="字幕字号" type="range" min="16" max="32" value="${S.size}" data-range="size"><span id="size-value">${S.size}px</span></div>`)}${setting('背景不透明度',`<div class="range"><input aria-label="背景不透明度" type="range" min="50" max="100" value="${S.opacity}" data-range="opacity"><span id="opacity-value">${S.opacity}%</span></div>`)}${setting('窗口位置',segments('dock',[[true,'停靠'],[false,'悬浮']]))}<div class="mini-caption">${caption()}</div>`;
if(S.settingsTab===1)body=`<h3>语言与翻译</h3>${setting('翻译方向','<span>英语 → 简体中文</span>')}${setting('显示内容',segments('bilingual',[[true,'双语'],[false,'仅中文']]))}${setting('阅读顺序',segments('originalFirst',[[false,'中文在上'],[true,'英文在上']]))}<div class="mini-caption">${caption()}</div>`;
if(S.settingsTab===2)body=`<h3>连接服务</h3><div style="height:20px"></div><div class="service"><div class="service-head"><strong>OpenAI</strong><span class="service-status">${S.connected?'已连接':'未连接'}</span></div><p>实时转录 · Luna 翻译</p><button class="small" data-action="connect">${S.connected?'检查连接':'连接'}</button></div><div class="service"><div class="service-head"><strong>Soniox</strong><span class="muted" style="font-size:10px">未连接</span></div><p>转录 · 说话人区分 · 翻译</p><button class="small" disabled>待配置</button></div>`;
if(S.settingsTab===3)body=`<h3>存储</h3>${setting('自动保存知识库',`<button class="toggle ${S.autoSave?'on':''}" role="switch" aria-label="自动保存知识库" aria-checked="${S.autoSave}" data-action="toggle-save"></button>`,'生成成功后保存在本地')}${setting('字幕记录','<span class="muted">手动导出</span>')}${setting('音频','<span class="muted">不保存</span>')}`;
return `<div class="modal-head"><h2>设置</h2><button class="text-btn icon-btn" data-action="close-settings" aria-label="关闭设置">✕</button></div><div class="settings-body"><nav class="settings-nav" aria-label="设置分类">${['字幕外观','语言与翻译','连接服务','存储'].map((x,i)=>`<button data-tab="${i}" class="${S.settingsTab===i?'active':''}">${x}</button>`).join('')}</nav><section class="settings-content">${body}</section></div><div class="modal-foot"><button class="primary small" data-action="close-settings">完成</button></div>`}
function openSettings(){const d=$('#settings');d.innerHTML=settingsContent();if(!d.open)d.showModal();paintCaptions()}
function openTerm(id){editId=id;const t=current().terms.find(t=>t.id===id);$('#term').innerHTML=`<div class="modal-head"><h2>${esc(t.term)}</h2><button class="text-btn" data-action="close-term" aria-label="关闭术语">✕</button></div><div class="detail-body"><p>${esc(t.meaning)}</p><label for="term-value">译法</label><input id="term-value" value="${esc(t.translation)}" maxlength="100">${current().url?`<a href="${current().url}" target="_blank" rel="noopener noreferrer">${esc(current().source)} ↗</a>`:''}</div><div class="modal-foot"><button class="primary small" data-action="save-term">保存</button></div>`;$('#term').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.go){go(d.go);return}if(d.domain!==undefined){S.domain=Number(d.domain);S.focus=domains[S.domain].focus[0]||'';render();return}if(d.focus){S.focus=d.focus;render();return}if(d.profile!==undefined){S.selected=Number(d.profile);S.search='';render();return}if(d.term!==undefined){openTerm(Number(d.term));return}if(d.tab!==undefined){S.settingsTab=Number(d.tab);openSettings();return}if(d.setting){S[d.setting]=d.value==='true'?true:d.value==='false'?false:d.value;if($('#settings').open)openSettings();else render();paintCaptions();return}switch(d.action){case'new':S.step=S.generating?1:0;go('setup');break;case'skip':go('workspace');break;case'generate':startGeneration();break;case'pause-generation':S.paused=!S.paused;render();break;case'cancel':clearInterval(generationTimer);S.generating=false;S.step=0;render();break;case'play':togglePlayback();break;case'settings':S.settingsTab=0;openSettings();break;case'connection':S.settingsTab=2;openSettings();break;case'close-settings':$('#settings').close();render();break;case'toggle-save':S.autoSave=!S.autoSave;openSettings();break;case'connect':b.disabled=true;b.textContent='连接中…';setTimeout(()=>{S.connected=true;if($('#settings').open)openSettings();notify('连接正常')},900);break;case'close-term':$('#term').close();break;case'save-term':{const v=$('#term-value').value.trim();if(!v){$('#term-value').focus();return}current().terms.find(t=>t.id===editId).translation=v;$('#term').close();render();notify('已保存');break}case'export':{const blob=new Blob([JSON.stringify(current(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='livecap-knowledge.example.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已导出');break}}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='custom'){S.custom=t.value;$('[data-action="generate"]').disabled=!S.custom.trim()}if(t.id==='search'){S.search=t.value;$('#term-rows').innerHTML=termRows()}if(t.dataset.range){const k=t.dataset.range;S[k]=Number(t.value);$('#'+k+'-value').textContent=t.value+(k==='size'?'px':'%');paintCaptions()}});
window.addEventListener('hashchange',()=>{let h=location.hash.slice(1);if(['setup','workspace','library'].includes(h)&&h!==S.view){S.view=h;render()}});
if(['setup','workspace','library'].includes(location.hash.slice(1)))S.view=location.hash.slice(1);render();

$('#settings').addEventListener('close',()=>{render()});
